import{_ as l,o as t,c as e,a2 as o}from"./chunks/framework.BWuWLRhz.js";const u=JSON.parse('{"title":"一体机联动","description":"ClassIsland 插件与 AgoraIn v4 服务端的对接方式","frontmatter":{"title":"一体机联动","description":"ClassIsland 插件与 AgoraIn v4 服务端的对接方式"},"headers":[],"relativePath":"plugin.md","filePath":"plugin.md","lastUpdated":1791170742000}'),d={name:"plugin.md"};function r(i,a,s,n,c,h){return t(),e("div",null,[...a[0]||(a[0]=[o('<h1 id="一体机联动-classisland-插件" tabindex="-1">一体机联动（ClassIsland 插件） <a class="header-anchor" href="#一体机联动-classisland-插件" aria-label="Permalink to &quot;一体机联动（ClassIsland 插件）&quot;">​</a></h1><p>教室一体机上运行的 ClassIsland 插件可以把「教师呼叫」「课表档案」与 AgoraIn 服务端打通： 教师端发起呼叫，一体机<strong>置顶弹窗 + 中文语音朗读</strong>提醒；课表由 AgoraIn 统一维护并推送到教室。</p><h2 id="工作方式" tabindex="-1">工作方式 <a class="header-anchor" href="#工作方式" aria-label="Permalink to &quot;工作方式&quot;">​</a></h2><table tabindex="0"><thead><tr><th>接口</th><th>方向</th><th>说明</th></tr></thead><tbody><tr><td><code>POST api/calls_register</code></td><td>插件 → 服务端</td><td>注册设备（教室名 / 设备标识 / 版本），返回设备密钥</td></tr><tr><td><code>POST api/calls_pull</code></td><td>插件 → 服务端</td><td>拉取待处理呼叫（待下课 / 应急 / 传唤）</td></tr><tr><td><code>POST api/calls_ack</code></td><td>插件 → 服务端</td><td>确认呼叫已展示（语音播报完成）</td></tr><tr><td><code>POST api/profile_pull</code></td><td>插件 → 服务端</td><td>拉取课表档案（含版本号，用于覆盖本地档案）</td></tr></tbody></table><ul><li>这些接口<strong>不带 <code>/api/v4</code> 前缀</strong>，使用设备密码鉴权（不是 JWT）</li><li>呼叫经 SignalR 实时下发，插件离线期间的呼叫会在重连后补拉</li></ul><h2 id="配置步骤" tabindex="-1">配置步骤 <a class="header-anchor" href="#配置步骤" aria-label="Permalink to &quot;配置步骤&quot;">​</a></h2><ol><li>在 AgoraIn 后台「设备」页注册一体机设备，记录设备标识与密码</li><li>在教室一体机上安装 ClassIsland 插件，填入服务器地址与设备凭据</li><li>插件启动后自动 <code>calls_register</code>，随后按心跳周期 <code>calls_pull</code></li><li>验证：在「设备」页查看该设备在线状态，并发起一条测试呼叫 —— 一体机应置顶弹窗并语音朗读</li></ol><h2 id="课表推送" tabindex="-1">课表推送 <a class="header-anchor" href="#课表推送" aria-label="Permalink to &quot;课表推送&quot;">​</a></h2><ol><li>AgoraIn 后台维护班级课表（可导入 CSES / ClassIsland 档案，JSON 或 YAML 均可）</li><li>「课程表 → 推送」把档案推送到班级绑定的一体机</li><li>插件通过 <code>profile_pull</code> 获取最新档案版本并覆盖本地；版本号未变化时不会重复覆盖</li></ol><blockquote><p>课表联动后，上课自动切大屏、下课切控制模式，并可联动课时自动扣减。</p></blockquote><h2 id="常见问题" tabindex="-1">常见问题 <a class="header-anchor" href="#常见问题" aria-label="Permalink to &quot;常见问题&quot;">​</a></h2><ul><li><strong>呼叫没有弹出</strong>：确认设备在线、插件版本支持当前接口；查服务端 <code>data/logs</code> 中对应时间的请求记录</li><li><strong>课表没更新</strong>：确认推送后档案版本号变化；插件需为支持 <code>profile_pull</code> 的版本</li><li><strong>语音不播报</strong>：检查一体机音频输出与插件语音开关</li></ul><h2 id="相关阅读" tabindex="-1">相关阅读 <a class="header-anchor" href="#相关阅读" aria-label="Permalink to &quot;相关阅读&quot;">​</a></h2><ul><li><a href="/features.html">功能特性</a> · <a href="/deploy.html">部署指南</a> · <a href="/faq.html">常见问题</a></li></ul>',14)])])}const _=l(d,[["render",r]]);export{u as __pageData,_ as default};
